<template>
  <main ref="root" class="case-detail-page" :style="{ '--detail-progress': `${progress}%` }">
    <div class="detail-progress" aria-hidden="true"><span></span></div>
    <section class="detail-hero detail-shell" data-reveal>
      <button class="detail-back" type="button" @click="backToList"><ArrowLeft aria-hidden="true" /> <span>{{ isEn ? 'Back to cases' : '返回案例列表' }}</span></button>
      <p class="detail-kicker">{{ localized(item?.categoryLabel, item?.categoryLabelEn) || (isEn ? 'Case study' : '企业案例') }}</p>
      <h1>{{ localized(item?.title, item?.titleEn) }}</h1>
      <p class="detail-summary">{{ localized(item?.summary, item?.summaryEn) }}</p>
      <div class="detail-meta"><span>{{ item?.publishedAt || '' }}</span><span>{{ (item?.technologies || []).join(' · ') }}</span><span>{{ source === 'mock' ? (isEn ? 'Demo data' : '演示数据') : (isEn ? 'Published' : '正式内容') }}</span></div>
    </section>
    <section v-if="item" class="detail-shell detail-body" data-reveal>
      <figure class="detail-cover"><img :src="item.cover?.src" :alt="localized(item.title, item.titleEn)" loading="eager"><figcaption>{{ isEn ? 'Project view' : '项目视图' }}</figcaption></figure>
      <div class="detail-layout">
        <article class="detail-copy"><p class="detail-kicker">01 / {{ isEn ? 'OVERVIEW' : '项目概览' }}</p><h2>{{ isEn ? 'Built around a real workflow.' : '围绕真实业务现场构建。' }}</h2><p>{{ localized(item.description || item.summary, item.descriptionEn || item.summaryEn) }}</p><div v-if="safeBody" class="rich-copy" v-html="safeBody"></div><a v-if="item.projectLink?.kind === 'url'" class="project-link" :href="item.projectLink.value" target="_blank" rel="noopener noreferrer">{{ isEn ? 'View project' : '查看项目' }} <TopRight aria-hidden="true" /></a><span v-else-if="item.projectLink" class="project-link project-link--text">{{ item.projectLink.value }}</span></article>
        <aside v-if="gallery.length" class="detail-gallery" aria-label="项目图集"><p class="detail-kicker">02 / {{ isEn ? 'GALLERY' : '图集' }}</p><button v-for="(image, index) in gallery" :key="image.id || image.src" type="button" class="gallery-item" @click="activeImage = image"><img :src="image.src" :alt="image.alt || `${item.title} ${index + 1}`" loading="lazy"><span>{{ String(index + 1).padStart(2, '0') }}</span></button></aside>
      </div>
      <div v-if="activeImage" class="lightbox" role="dialog" aria-modal="true" @click.self="activeImage = null"><button type="button" class="lightbox-close" :aria-label="isEn ? 'Close image' : '关闭图片'" @click="activeImage = null">×</button><img :src="activeImage.src" :alt="activeImage.alt"></div>
    </section>
    <section v-else-if="notFound" class="detail-empty detail-shell" data-reveal><p class="detail-kicker">404 / {{ isEn ? 'NOT FOUND' : '未找到' }}</p><h1>{{ isEn ? 'This case is unavailable.' : '暂未找到这个案例。' }}</h1><p>{{ isEn ? 'The ID may be incorrect or the project is no longer published.' : '案例 ID 不正确，或项目尚未发布。' }}</p><button type="button" class="project-link" @click="backToList">{{ isEn ? 'Back to cases' : '返回案例列表' }} <ArrowLeft aria-hidden="true" /></button></section>
    <section v-else-if="loadError" class="detail-empty detail-shell" data-reveal><p class="detail-kicker">{{ isEn ? 'TEMPORARY ERROR' : '暂时不可用' }}</p><h1>{{ isEn ? 'This case could not be loaded.' : '案例暂时无法加载。' }}</h1><button type="button" class="project-link" @click="loadDetail">{{ isEn ? 'Retry' : '重新加载' }}</button></section>
    <div v-else class="detail-loading detail-shell">{{ isEn ? 'Loading case…' : '案例加载中…' }}</div>
  </main>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { ArrowLeft, TopRight } from '@element-plus/icons-vue'
import { useRoute, useRouter } from 'vue-router'
import { getCase } from '@/repositories/content'
const route = useRoute(); const router = useRouter(); const root = ref(null); const item = ref(null); const source = ref('api'); const notFound = ref(false); const loadError = ref(false); const progress = ref(0); const activeImage = ref(null); let revealObserver
const isEn = computed(() => route.path.startsWith('/en/')); const localized = (zh, en) => isEn.value ? (en || zh || '') : (zh || en || ''); const gallery = computed(() => item.value?.gallery || (item.value?.cover ? [item.value.cover] : []))
const safeHtml = (html) => { if (typeof window === 'undefined') return ''; const doc = new DOMParser().parseFromString(String(html || ''), 'text/html'); doc.querySelectorAll('script,style,iframe,object,embed,form,link,meta').forEach(node => node.remove()); doc.body.querySelectorAll('*').forEach(node => Array.from(node.attributes).forEach(attribute => { const name = attribute.name.toLowerCase(); const value = attribute.value.trim(); if (name.startsWith('on') || name === 'style' || ((name === 'href' || name === 'src') && !/^(https?:|\/|#)/i.test(value))) node.removeAttribute(attribute.name) })); return doc.body.innerHTML }
const safeBody = computed(() => safeHtml(isEn.value ? (item.value?.bodyHtmlEn || item.value?.bodyHtml) : item.value?.bodyHtml)); const backToList = () => router.push(isEn.value ? '/en/cases' : '/cases')
const updateProgress = () => { const max = document.documentElement.scrollHeight - window.innerHeight; progress.value = max > 0 ? Math.min(100, Math.max(0, window.scrollY / max * 100)) : 0 }
async function loadDetail () { item.value = null; notFound.value = false; loadError.value = false; try { const result = await getCase({ id: String(route.params.id) }); item.value = result.item; source.value = result.source } catch (error) { notFound.value = error?.type === 'not-found'; loadError.value = !notFound.value } }
onMounted(async () => { window.addEventListener('scroll', updateProgress, { passive: true }); await loadDetail(); updateProgress(); revealObserver = 'IntersectionObserver' in window ? new IntersectionObserver(entries => entries.forEach(entry => entry.target.classList.toggle('is-visible', entry.isIntersecting)), { threshold: .12 }) : null; if (revealObserver) root.value?.querySelectorAll('[data-reveal]').forEach(node => revealObserver.observe(node)); else root.value?.querySelectorAll('[data-reveal]').forEach(node => node.classList.add('is-visible')) })
onBeforeUnmount(() => { revealObserver?.disconnect(); window.removeEventListener('scroll', updateProgress) })
</script>

<style scoped>
