-ink-body);font-size:17px;line-height:1.9}.rich-copy{max-width:600px;margin-top:32px;color:var(--color-ink-body);font-size:16px;line-height:2}.rich-copy :deep(h2){margin:38px 0 12px;color:var(--color-ink);font-size:25px}.rich-copy :deep(p){margin:0 0 18px}.project-link{display:inline-flex;align-items:center;gap:12px;margin-top:38px;padding:14px 0;border-bottom:1px solid var(--color-ink);color:var(--color-ink);font:inherit;text-decoration:none}.detail-gallery{border-top:1px solid var(--color-line);padding-top:22px}.gallery-item{position:relative;display:block;width:100%;margin-top:20px;padding:0;border:0;background:none;cursor:pointer;text-align:left}.gallery-item img{display:block;width:100%;aspect-ratio:1.35;object-fit:cover;transition:transform .7s ease}.gallery-item:hover img{transform:scale(1.04)}.gallery-item span{position:absolute;top:12px;left:12px;color:#fff;font-size:11px}.detail-empty{padding-top:180px;min-height:70vh}.detail-empty h1{max-width:760px;margin:22px 0;font-size:clamp(46px,7vw,90px);font-weight:500;line-height:1}.detail-empty p:not(.detail-kicker){color:var(--color-ink-soft);font-size:18px}.detail-loading{padding-top:190px;color:var(--color-ink-soft)}.lightbox{position:fixed;inset:0;z-index:30;display:grid;place-items:center;padding:5vw;background:rgba(0,0,0,.86)}.lightbox img{max-width:92vw;max-height:88vh;object-fit:contain}.lightbox-close{position:absolute;top:22px;right:28px;color:#fff;background:none;border:0;font-size:34px;cursor:pointer}@media(max-width:760px){.detail-shell{width:min(88%,640px)}.detail-hero{padding-top:120px;padding-bottom:60px}.detail-back{margin-bottom:62px}.detail-summary{font-size:17px}.detail-meta{gap:12px 20px;margin-top:32px}.detail-cover{margin-bottom:64px}.detail-layout{display:block}.detail-gallery{margin-top:70px}.detail-progress{top:64px}.detail-empty{padding-top:140px}}@media(prefers-reduced-motion:reduce){.detail-body{opacity:1;transform:none}.detail-cover img,.gallery-item img{transition:none}}
</style>
